create extension if not exists "pgcrypto";
create type machine_status as enum ('Active','Inactive','Maintenance','Down');
create type defect_severity as enum ('Low','Medium','High','Critical');
create type defect_status as enum ('Pending','Resolved','Closed');
create type maintenance_action as enum ('Repair','Part Replacement','PM','Inspection');
create table departments (id uuid primary key default gen_random_uuid(), name text unique not null, created_at timestamptz default now());
create table areas (id uuid primary key default gen_random_uuid(), department_id uuid references departments(id) on delete set null, name text not null, unique(department_id,name));
create table profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'viewer' check (role in ('admin','technician','viewer')), created_at timestamptz default now());
create table machines (id uuid primary key default gen_random_uuid(), machine_code text unique not null, scope text, name text not null, manufacturer text, model text, serial_number text, operating_range text, operation_date date, status machine_status not null default 'Active', department_id uuid references departments(id), area_id uuid references areas(id), created_at timestamptz default now(), updated_at timestamptz default now());
create table machine_status_logs (id uuid primary key default gen_random_uuid(), machine_id uuid not null references machines(id) on delete cascade, old_status machine_status, new_status machine_status not null, reason text, changed_by uuid references profiles(id), created_at timestamptz default now());
create table spare_parts (id uuid primary key default gen_random_uuid(), part_code text unique not null, name text not null, lifetime_months int not null check (lifetime_months > 0), description text, is_active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table breakdown_records (id uuid primary key default gen_random_uuid(), defect_code text unique not null, machine_id uuid not null references machines(id) on delete cascade, date_found date not null, symptom text not null, severity defect_severity not null, reported_by text not null, status defect_status not null default 'Pending', root_cause text, corrective_action text, resolved_by text, resolved_at timestamptz, downtime_minutes int check (downtime_minutes is null or downtime_minutes >= 0), linked_maintenance_id uuid, created_at timestamptz default now());
create table spare_part_replacement_records (id uuid primary key default gen_random_uuid(), machine_id uuid not null references machines(id) on delete cascade, spare_part_id uuid not null references spare_parts(id), replacement_date date not null, next_due_date date, operator_name text not null, notes text, created_at timestamptz default now());
create table preventive_maintenance_plans (id uuid primary key default gen_random_uuid(), machine_id uuid not null references machines(id) on delete cascade, name text not null, frequency_days int not null check (frequency_days > 0), checklist text, next_due_date date not null, is_active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table preventive_maintenance_records (id uuid primary key default gen_random_uuid(), plan_id uuid references preventive_maintenance_plans(id) on delete set null, machine_id uuid not null references machines(id) on delete cascade, performed_date date not null, completed_by text not null, result text not null, notes text, created_at timestamptz default now());
create table settings (key text primary key, value jsonb not null, updated_at timestamptz default now());
create index on machines(status); create index on breakdown_records(machine_id,status,severity); create index on spare_part_replacement_records(machine_id,next_due_date); create index on preventive_maintenance_plans(machine_id,next_due_date) where is_active; create index on preventive_maintenance_records(machine_id,performed_date);
alter table departments enable row level security; alter table areas enable row level security; alter table profiles enable row level security; alter table machines enable row level security; alter table machine_status_logs enable row level security; alter table spare_parts enable row level security; alter table breakdown_records enable row level security; alter table spare_part_replacement_records enable row level security; alter table preventive_maintenance_plans enable row level security; alter table preventive_maintenance_records enable row level security; alter table settings enable row level security;
create policy "authenticated read" on departments for select to authenticated using (true); create policy "authenticated read" on areas for select to authenticated using (true); create policy "authenticated read" on machines for select to authenticated using (true); create policy "authenticated read" on spare_parts for select to authenticated using (true); create policy "authenticated read" on breakdown_records for select to authenticated using (true); create policy "authenticated read" on spare_part_replacement_records for select to authenticated using (true); create policy "authenticated read" on preventive_maintenance_plans for select to authenticated using (true); create policy "authenticated read" on preventive_maintenance_records for select to authenticated using (true); create policy "own profile read" on profiles for select to authenticated using (auth.uid()=id);
create policy "technician write machines" on machines for all to authenticated using (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician'))) with check (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician')));
create policy "technician write parts" on spare_parts for all to authenticated using (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician'))) with check (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician')));
create policy "technician write breakdowns" on breakdown_records for all to authenticated using (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician'))) with check (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician')));
create policy "technician write replacements" on spare_part_replacement_records for all to authenticated using (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician'))) with check (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician')));
create policy "technician write pm" on preventive_maintenance_plans for all to authenticated using (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician'))) with check (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician')));
create policy "technician write pm records" on preventive_maintenance_records for all to authenticated using (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician'))) with check (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('admin','technician')));
